import{_ as o,C as d,o as r,c as s,j as e,a as i,E as l,al as n}from"./chunks/framework.7vp1BMOE.js";const y=JSON.parse('{"title":"AEDROX AEDROXH7","description":"","frontmatter":{},"headers":[],"relativePath":"zh/flight_controller/aedrox_aedroxh7.md","filePath":"zh/flight_controller/aedrox_aedroxh7.md"}'),h={name:"zh/flight_controller/aedrox_aedroxh7.md"};function c(p,t,u,b,m,f){const a=d("Badge");return r(),s("div",null,[t[0]||(t[0]=e("h1",{id:"aedrox-aedroxh7",tabindex:"-1"},[i("AEDROX AEDROXH7 "),e("a",{class:"header-anchor",href:"#aedrox-aedroxh7","aria-label":'Permalink to "AEDROX AEDROXH7"'},"​")],-1)),l(a,{type:"tip",text:"PX4 v1.18"}),t[1]||(t[1]=n('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot. Contact the <a href="https://www.aedrox.com/" target="_blank" rel="noreferrer">manufacturer</a> for hardware support.</p></div><p>The AEDROXH7 is an STM32H743-based FPV / racing flight controller from AEDROX.</p><p>For full hardware documentation and pinouts, see the <a href="https://aedrox.gitbook.io/docs" target="_blank" rel="noreferrer">manufacturer documentation</a>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./../flight_controller/autopilot_manufacturer_supported">manufacturer supported</a>.</p></div><h2 id="主要特性" tabindex="-1">主要特性 <a class="header-anchor" href="#主要特性" aria-label="Permalink to &quot;主要特性&quot;">​</a></h2><ul><li>MCU: STM32H743VIM6 32-bit processor running at 480 MHz</li><li>IMU: ICM-42688-P</li><li>Barometer: DPS310 (some revisions ship DPS368, supported by the same driver)</li><li>128 MB W25N NAND flash for logging (mounted as littlefs at <code>/fs/flash</code>)</li><li>MAX7456 analog OSD</li><li>6 UARTs (TEL1, GPS1, RC, TEL2, ESC telemetry, DJI/MSP HD OSD / debug console)</li><li>1 internal I2C bus (barometer), 1 external I2C bus (user connector)</li><li>1 CAN bus (CAN1) with silent-pin control</li><li>8 PWM motor outputs (Bidirectional DShot capable)</li><li>1 addressable LED strip pad, 2 general GPIO</li><li>Battery voltage and current monitoring</li><li>USB Type-C</li></ul><p>No on-board magnetometer; PX4 runs with <code>SYS_HAS_MAG=0</code> and EKF2 gravity fusion enabled by default.</p><h2 id="store" tabindex="-1">Where to Buy <a class="header-anchor" href="#store" aria-label="Permalink to &quot;Where to Buy {#store}&quot;">​</a></h2><ul><li><a href="https://www.aedrox.com/" target="_blank" rel="noreferrer">aedrox.com</a>.</li></ul><h2 id="connectors-and-pins" tabindex="-1">Connectors and Pins <a class="header-anchor" href="#connectors-and-pins" aria-label="Permalink to &quot;Connectors and Pins&quot;">​</a></h2><h3 id="uarts" tabindex="-1">UARTs <a class="header-anchor" href="#uarts" aria-label="Permalink to &quot;UARTs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Port</th><th>MCU peripheral</th><th>设备</th><th>功能</th></tr></thead><tbody><tr><td><code>SERIAL1</code></td><td>USART1</td><td>/dev/ttyS0</td><td>TELEM1 (MAVLink)</td></tr><tr><td><code>SERIAL2</code></td><td>USART2</td><td>/dev/ttyS1</td><td>GPS1</td></tr><tr><td><code>SERIAL3</code></td><td>USART3</td><td>/dev/ttyS2</td><td>遥控输入</td></tr><tr><td><code>SERIAL4</code></td><td>UART4</td><td>/dev/ttyS3</td><td>TELEM2</td></tr><tr><td><code>SERIAL7</code></td><td>UART7</td><td>/dev/ttyS4</td><td>ESC telemetry (RX only)</td></tr><tr><td><code>SERIAL8</code></td><td>UART8</td><td>/dev/ttyS5</td><td>Debug shell (system console)</td></tr></tbody></table><p><code>SERIAL7</code> is wired RX-only by the vendor (intended for ESC telemetry). <code>SERIAL8</code> is the system console at 57600 8N1 (device: <code>/dev/ttyS5</code>).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The vendor brings <code>SERIAL8</code> out on the HD VTX connector (intended for DJI / MSP DisplayPort), but the default PX4 config uses it as the system console. To use it for MSP DisplayPort instead, move the console off UART8, then start the <a href="./../modules/modules_driver#msp-osd">msp_osd</a> driver on <code>/dev/ttyS5</code>.</p></div><h3 id="pwm_outputs" tabindex="-1">PWM Outputs <a class="header-anchor" href="#pwm_outputs" aria-label="Permalink to &quot;PWM Outputs {#pwm_outputs}&quot;">​</a></h3><p>8 PWM motor outputs (M1-M8), all <a href="./../peripherals/dshot">DShot</a> and <a href="./../peripherals/dshot#bidirectional-dshot-telemetry">Bidirectional DShot</a> (RPM telemetry) capable.</p><p>The M5-M8 motor connector additionally exposes two user-controllable GPIOs (<code>GPIO1</code> / <code>GPIO2</code>, on PA2 / PA3) alongside the motor signals. Toggle them at runtime with the <code>gpio</code> command (see &quot;User GPIOs&quot; below).</p><p>A separate addressable-LED-strip pad is brought out; currently driven as a plain GPIO in this port .</p><h3 id="status-leds" tabindex="-1">Status LEDs <a class="header-anchor" href="#status-leds" aria-label="Permalink to &quot;Status LEDs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Silkscreen</th><th>MCU pin</th><th>颜色</th><th>功能</th></tr></thead><tbody><tr><td>LED1</td><td>PE2</td><td>蓝色</td><td>MCU activity, solid when armed</td></tr><tr><td>LED2</td><td>-</td><td>绿色</td><td>IMU power-supply indicator</td></tr><tr><td>LED3</td><td>-</td><td>绿色</td><td>MCU / baro / OSD power-supply indicator</td></tr><tr><td>LED4</td><td>PE5</td><td>绿色</td><td>MCU activity, blinks based on flight state (preflight / disarmed / failsafe)</td></tr><tr><td>LED5</td><td>-</td><td>-</td><td>10v VTX rail indicator (lit when VTX power is enabled)</td></tr></tbody></table><h3 id="other-i-o" tabindex="-1">Other I/O <a class="header-anchor" href="#other-i-o" aria-label="Permalink to &quot;Other I/O&quot;">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>MCU pin</th><th>备注</th></tr></thead><tbody><tr><td>蜂鸣器</td><td>PA7</td><td>Drives an NPN low-side switch, use a basic 2-pin active buzzer (e.g. TMB12A05)</td></tr><tr><td>VTX power</td><td>PB1</td><td>Active high</td></tr><tr><td>Camera switch</td><td>PD15</td><td>Active high, currently hard-coded to camera 1 at boot (no runtime control yet); use <code>gpio write D15 1</code> from nsh to switch to camera 2</td></tr><tr><td>PINIO 1 / 2</td><td>PA2 / PA3</td><td>User-controllable GPIOs via <code>gpio</code> command</td></tr><tr><td>CAN1 silent</td><td>PD12</td><td>Driven low to enable CAN bus</td></tr><tr><td>Battery V sense</td><td>PC0</td><td>ADC1 IN10, calibrate <code>BAT1_V_DIV</code> per build</td></tr><tr><td>Battery I sense</td><td>PC1</td><td>ADC1 IN11, calibrate <code>BAT1_A_PER_V</code> per ESC, or use DShot telemetry for current (<code>BAT1_SOURCE</code>)</td></tr><tr><td>USB VBUS sense</td><td>PC15</td><td>Non-standard pin for VBUS sense</td></tr></tbody></table><h3 id="analog-osd-max7456" tabindex="-1">Analog OSD (MAX7456) <a class="header-anchor" href="#analog-osd-max7456" aria-label="Permalink to &quot;Analog OSD (MAX7456)&quot;">​</a></h3><p>The MAX7456 driver is built in but disabled by default. To enable, set <a href="./../advanced_config/parameter_reference#OSD_ATXXXX_CFG"><code>OSD_ATXXXX_CFG</code></a> to <code>1</code> (NTSC) or <code>2</code> (PAL) and reboot. The <code>atxxxx</code> driver auto-starts and overlays PX4 status on top of the camera video.</p><h2 id="px4-bootloader-update" tabindex="-1">PX4 Bootloader Update <a class="header-anchor" href="#px4-bootloader-update" aria-label="Permalink to &quot;PX4 Bootloader Update&quot;">​</a></h2><p>Before PX4 firmware can be installed, the PX4 bootloader must be flashed. Download the <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/aedrox/aedroxh7/extras/aedrox_aedroxh7_bootloader.bin" target="_blank" rel="noreferrer">aedrox_aedroxh7_bootloader.bin</a> bootloader binary and follow the <a href="./../advanced_config/bootloader_update_from_betaflight">bootloader update from Betaflight / DFU</a> flashing instructions.</p><h2 id="编译固件" tabindex="-1">编译固件 <a class="header-anchor" href="#编译固件" aria-label="Permalink to &quot;编译固件&quot;">​</a></h2><p>To <a href="./../dev_setup/building_px4">build PX4</a> for this target:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aedrox_aedroxh7_default</span></span></code></pre></div><h2 id="installing-px4-firmware" tabindex="-1">Installing PX4 Firmware <a class="header-anchor" href="#installing-px4-firmware" aria-label="Permalink to &quot;Installing PX4 Firmware&quot;">​</a></h2><p>Firmware can be installed in any of the normal ways:</p><ul><li><p>Build and upload the source:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aedrox_aedroxh7_default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upload</span></span></code></pre></div></li><li><p><a href="./../config/firmware">Load the firmware</a> using <em>QGroundControl</em>. You can use either pre-built firmware or your own custom firmware.</p></li></ul><h3 id="flash-storage-troubleshooting" tabindex="-1">Flash Storage Troubleshooting <a class="header-anchor" href="#flash-storage-troubleshooting" aria-label="Permalink to &quot;Flash Storage Troubleshooting&quot;">​</a></h3><p>The AEDROXH7 uses a 128 MB NAND flash (W25N) with a littlefs filesystem for <a href="./../dev_log/logging">logging</a>. If the flash filesystem becomes corrupted, you can reformat it from the <a href="./../debug/system_console">System Console</a>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mklittlefs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/mtd0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /fs/flash</span></span></code></pre></div><p>This will erase all data on the flash and create a fresh littlefs filesystem. The filesystem is immediately available after the command completes.</p><h3 id="系统控制台" tabindex="-1">系统控制台 <a class="header-anchor" href="#系统控制台" aria-label="Permalink to &quot;系统控制台&quot;">​</a></h3><p>UART8 is configured for use as the <a href="./../debug/system_console">System Console</a> at 57600 8N1.</p>',38))])}const P=o(h,[["render",c]]);export{y as __pageData,P as default};
